const item = $('Webhook WAHA').first().json;
const lookup = $input.first().json || {};
const body = item.body || {};
const payload = body.payload || {};

const event = body.event || null;
const rawFrom = String(payload.from || '');
const digits = (value) => String(value || '').replace(/[^0-9]/g, '');

// A chat WhatsApp addresses by LID shows up as <lid>@lid, and a reply sent to
// <lid>@c.us is rejected by WhatsApp Web. The lids lookup turns it into the
// real <phone>@c.us, which is also the key the outbound flow stores in
// anteraja_chat_state.
const pn = typeof lookup.pn === 'string' && lookup.pn !== '' ? lookup.pn : '';
const chatId = pn !== '' ? pn : rawFrom;

const text = String(payload.body || '').trim();
const phone = digits(pn !== '' ? pn : rawFrom);
const isGroup = rawFrom.endsWith('@g.us');
const isStatus = rawFrom === 'status@broadcast';
const shouldProcess = event === 'message'
  && payload.fromMe !== true
  && !isGroup
  && !isStatus
  && text.length > 0
  && phone.length >= 8;

return [{ json: {
  should_process: shouldProcess,
  phone: phone,
  chat_id: chatId,
  text: text,
  push_name: payload.notifyName || null
} }];

const msg = $('Normalisasi').first().json;
const match = String(msg.text || '').toUpperCase().match(/AJ-FRZ-\d{4,}/);

return [{ json: { resi: match ? match[0] : null } }];

const msg = $('Normalisasi').first().json;
const state = $('Ambil State').first().json || {};
const lookup = $input.first().json || {};
const detected = $('Deteksi Resi').first().json || {};

const slots = ['09:00-11:00', '11:00-13:00', '13:00-15:00', '15:00-17:00', '17:00-19:00'];
const today = $now.setZone('Asia/Jakarta').toFormat('yyyy-LL-dd');

// A resi the customer typed wins over the stored state only when it names a
// different package; otherwise whatever the app last notified them about stands.
const found = lookup.found === true;
const attached = found && (!state.tracking_number || state.tracking_number !== lookup.tracking_number);

const tracking = attached ? lookup.tracking_number : (state.tracking_number || null);
const token = attached ? lookup.client_token : (state.client_token || null);
const template = attached ? (lookup.template || 'none') : (state.last_template || 'none');
const statusLabel = attached ? (lookup.status_label || null) : null;
const clientUrl = attached ? (lookup.client_url || null) : null;

const system = [
  'Anda asisten operasional Anteraja Frozen yang membaca balasan pembeli di WhatsApp.',
  'Balas HANYA dengan JSON valid tanpa penjelasan tambahan.',
  'Skema: {"intent":"confirm_schedule|request_reschedule|choose_option|other","option":null,"proposed_date":null,"proposed_slot":null,"confidence":0.0}',
  'Aturan:',
  '- confirm_schedule: pembeli menyetujui jadwal penerimaan paket.',
  '- request_reschedule: pembeli meminta jadwal lain; isi proposed_date (YYYY-MM-DD, hari ini ' + today + ') dan proposed_slot dari daftar: ' + slots.join(', ') + '.',
  '- choose_option: pembeli memilih opsi penyelesaian kendala pada menu; isi option 1-4.',
  '- Frasa "kirim ulang" atau "ganti barang" berarti choose_option dengan option 2; "kembalikan", "retur", atau "batalkan" berarti option 1; "lanjutkan" atau "kompensasi" berarti option 3; "mau diskusi" atau "mau tanya" berarti option 4.',
  '- other: maksud tidak jelas.',
  'Konteks: pesan terakhir dari sistem = ' + template + '; resi = ' + (tracking || 'tidak diketahui') + '.'
].join('\n');

return [{ json: {
  phone: msg.phone,
  chat_id: msg.chat_id,
  text: msg.text,
  push_name: msg.push_name,
  tracking_number: tracking,
  client_token: token,
  last_template: template,
  status_label: statusLabel,
  client_url: clientUrl,
  resi_attempt: detected.resi || null,
  lookup_found: found,
  today: today,
  slots: slots,
  llm_body: {
    model: 'deepseek-v4-flash',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: msg.text }
    ]
  }
} }];

const ctx = $('Siapkan Konteks').first().json;
const llm = $input.first().json || {};

let llmIntent = null;
let llmOption = null;
let llmDate = null;
let llmSlot = null;
let confidence = 0;

try {
  const content = llm.choices && llm.choices[0] && llm.choices[0].message ? llm.choices[0].message.content : null;
  if (typeof content === 'string') {
    const parsed = JSON.parse(content);
    llmIntent = parsed.intent || null;
    llmOption = parsed.option === undefined || parsed.option === null ? null : parseInt(parsed.option, 10);
    confidence = parsed.confidence || 0;
    llmDate = parsed.proposed_date || null;
    llmSlot = parsed.proposed_slot || null;
  }
} catch (error) {
  llmIntent = null;
}

const text = String(ctx.text || '').toLowerCase().trim();
const template = ctx.last_template || 'none';
const slots = ctx.slots || [];
const resi = ctx.tracking_number || '-';
const link = ctx.client_url || null;
const base = ctx.client_token ? 'http://anteraja-hackathon-service/api/guest/' + ctx.client_token : null;
const has = (pattern) => pattern.test(text);

// What was this conversation waiting for? Only that step can be acted on.
let action = null;
let option = null;
let proposedDate = null;
let proposedSlot = null;

if (template === 'schedule_request') {
  // Whole words only: "besok" must not read as the "ok" confirmation.
  const wantsReschedule = has(/\b(jadwal lain|minta jadwal|ubah|ganti|tunda|reschedule|besok|tanggal|jam|pukul)\b/) || llmIntent === 'request_reschedule';
  const wantsConfirm = has(/\b(siap|ya|iya|oke|ok|bisa|setuju|terima|konfirmasi|hadir)\b/) || llmIntent === 'confirm_schedule';

  if (wantsReschedule && !wantsConfirm) {
    action = 'reschedule';
  } else if (wantsConfirm && !wantsReschedule) {
    action = 'confirm';
  } else if (llmIntent === 'request_reschedule') {
    action = 'reschedule';
  } else if (llmIntent === 'confirm_schedule') {
    action = 'confirm';
  } else if (wantsReschedule) {
    action = 'reschedule';
  } else if (wantsConfirm) {
    action = 'confirm';
  }

  if (action === 'reschedule') {
    proposedDate = llmDate;
    proposedSlot = llmSlot;
  }
} else if (template === 'issue_options') {
  if (/^[1-4]$/.test(text)) {
    action = 'choice';
    option = parseInt(text, 10);
  } else if (has(/(kirim ulang|dikirim ulang|pengiriman ulang|ganti barang|resend)/)) {
    action = 'choice';
    option = 2;
  } else if (has(/(kembali|retur|batal|tidak jadi)/)) {
    action = 'choice';
    option = 1;
  } else if (has(/(lanjut|kompensasi)/)) {
    action = 'choice';
    option = 3;
  } else if (has(/(diskusi|tanya|bicara)/)) {
    action = 'choice';
    option = 4;
  } else if (llmIntent === 'choose_option' && llmOption >= 1 && llmOption <= 4) {
    action = 'choice';
    option = llmOption;
  }
}

if (action && !base) {
  // The app never told us which package this is, so nothing can be applied.
  action = null;
}

let appUrl = null;
let appBody = {};
let reply = null;
let nextTemplate = null;

if (action === 'confirm') {
  appUrl = base + '/schedule/confirm';
  reply = 'Terima kasih, Kak! Jadwal penerimaan paket ' + resi + ' sudah dikonfirmasi dan paket akan kami antar sesuai jadwal. Anteraja Frozen \u2744\ufe0f';
  nextTemplate = 'confirmed';
} else if (action === 'reschedule' && proposedDate && proposedSlot && slots.indexOf(proposedSlot) !== -1) {
  appUrl = base + '/schedule/reschedule';
  appBody = { date: proposedDate, slot: proposedSlot };
  reply = 'Terima kasih, Kak! Permintaan jadwal ulang resi ' + resi + ' pada ' + proposedDate + ' (' + proposedSlot + ') sudah kami terima. Admin akan mengusulkan jadwal barunya. Anteraja Frozen \u2744\ufe0f';
  nextTemplate = 'reschedule_requested';
} else if (action === 'choice' && option >= 1 && option <= 4) {
  appUrl = base + '/issue/choice';
  appBody = { choice: option };
  const opsi = {
    1: 'Baik Kak, paket akan kami proses untuk pengembalian ke pengirim. Tim kami menindaklanjuti klaim sesuai ketentuan layanan.',
    2: 'Baik Kak, kami siapkan pengiriman ulang paket. Silakan konfirmasi jadwal penerimaan yang Kakak inginkan.',
    3: 'Baik Kak, pengiriman tetap dilanjutkan dengan penawaran kompensasi sesuai ketentuan layanan kami.',
    4: 'Baik Kak, tim operasional kami akan menghubungi Kakak untuk diskusi lebih lanjut.'
  };
  reply = opsi[option] + ' Anteraja Frozen \u2744\ufe0f';
  nextTemplate = 'issue_choice_recorded';
} else if (action === 'reschedule') {
  reply = 'Baik Kak, mohon tuliskan tanggal dan pilihan jam penerimaan: ' + slots.join(', ') + '. Anteraja Frozen \u2744\ufe0f';
} else if (template === 'schedule_request') {
  reply = 'Paket ' + resi + ' masih menunggu konfirmasi jadwal. Balas *SIAP* untuk konfirmasi, atau *JADWAL LAIN* untuk meminta jadwal pengganti. Anteraja Frozen \u2744\ufe0f';
} else if (template === 'issue_options') {
  reply = 'Paket ' + resi + ' terkendala. Mohon balas angka 1, 2, 3, atau 4 sesuai opsi penyelesaian kendala. Anteraja Frozen \u2744\ufe0f';
} else if (template === 'delivered') {
  reply = 'Paket ' + resi + ' sudah diterima. Terima kasih telah menggunakan Anteraja Frozen! \u2744\ufe0f';
} else if (template === 'courier_arrived') {
  reply = 'Kurir kami sudah tiba di lokasi untuk paket ' + resi + '. Mohon siapkan penerimaan paket beku ya, Kak. \u2744\ufe0f';
} else if (template === 'on_the_way' || template === 'in_delivery') {
  reply = 'Paket ' + resi + ' sedang dalam pengiriman.' + (link ? ' Lacak di sini: ' + link : '') + ' Anteraja Frozen \u2744\ufe0f';
} else if (template === 'issue_decision' || template.indexOf('issue_decision_update') === 0) {
  reply = 'Paket ' + resi + ' sedang ditangani tim operasional kami.' + (link ? ' Pembaruan: ' + link : '') + ' Anteraja Frozen \u2744\ufe0f';
} else if (ctx.resi_attempt && !ctx.lookup_found) {
  reply = 'Nomor resi ' + ctx.resi_attempt + ' tidak terdaftar untuk nomor WhatsApp ini. Pastikan resinya benar dan nomor ini adalah nomor pembeli yang terdaftar pada pengiriman tersebut, atau hubungi layanan pelanggan Anteraja Frozen. \u2744\ufe0f';
} else if (link) {
  reply = 'Info paket ' + resi + ': ' + link + ' Anteraja Frozen \u2744\ufe0f';
} else {
  reply = 'Halo! \ud83d\udc4b Kirimkan nomor resi (contoh: AJ-FRZ-0012345) agar kami bisa membantu, atau hubungi layanan pelanggan Anteraja Frozen. \u2744\ufe0f';
}

return [{ json: {
  intent: action || 'info:' + template,
  option: option,
  confidence: confidence,
  app_url: appUrl,
  app_body: appBody,
  reply_text: reply,
  next_template: nextTemplate,
  phone: ctx.phone,
  tracking_number: ctx.tracking_number,
  client_token: ctx.client_token
} }];

const decision = $('Putuskan Aksi').first().json;
const msg = $('Normalisasi').first().json;

function appMessage(raw) {
  const brace = String(raw || '').indexOf('{');
  if (brace >= 0) {
    try {
      const parsed = JSON.parse(String(raw).slice(brace));
      if (parsed && parsed.message) return parsed.message;
    } catch (error) {
      // Not a JSON body; fall back to the generic line below.
    }
  }
  return null;
}

let text = decision.reply_text;
let ok = true;

try {
  const app = $('Panggil App').first().json;
  if (app && app.error) {
    ok = false;
    text = appMessage(app.error.message) || 'Mohon maaf, permintaan ini belum dapat kami proses.';
  } else if (app && app.success === false) {
    ok = false;
    text = app.message || 'Mohon maaf, permintaan ini belum dapat kami proses.';
  }
} catch (error) {
  // No app call on this path: the decided reply stands.
}

// The state row keeps whatever we already knew; a failed action must not
// advance last_template, so the pending step can still be answered.
return [{ json: {
  text: text,
  chat_id: msg.chat_id,
  phone: msg.phone,
  values: [
    msg.phone,
    decision.tracking_number || null,
    decision.client_token || null,
    ok ? (decision.next_template || null) : null,
    JSON.stringify({
      last_inbound_text: msg.text,
      last_intent: decision.intent,
      last_inbound_at: new Date().toISOString()
    })
  ]
} }];
